package com.edgeos.launcher; import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.content.*;import android.widget.*;import java.util.*;
public class SearchActivity extends Activity{ArrayList<AppInfo> apps;LinearLayout results;public void onCreate(Bundle b){super.onCreate(b);apps=AppRepository.load(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(18,28,18,18);root.setBackgroundColor(0xFF111318);EditText q=new EditText(this);q.setHint("Search");q.setHintTextColor(0xFFAAAAAA);q.setTextColor(Color.WHITE);q.setSingleLine();root.addView(q,new LinearLayout.LayoutParams(-1,60));results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.addView(results);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render(s.toString());}public void afterTextChanged(android.text.Editable e){}});setContentView(root);q.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(q,InputMethodManager.SHOW_IMPLICIT);render("");}void render(String q){results.removeAllViews();int n=0;for(AppInfo a:apps)if(q.isEmpty()||a.label.toLowerCase().contains(q.toLowerCase())){TextView t=Ui.text(this,"  "+a.label,18,Color.WHITE);t.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);t.setPadding(10,0,0,0);t.setOnClickListener(v->{Intent i=getPackageManager().getLaunchIntentForPackage(a.pkg);if(i!=null)startActivity(i);});results.addView(t,new LinearLayout.LayoutParams(-1,58));if(++n>30)break;}}}
